#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    vector<long long> dp_list = {0, 1};
    long long total = 1;

    for (int i = 2; i <= n; ++i) {
        int max_check = (int) sqrt(i) + 1;
        long long current_total = total;

        for (int f = 2; f < max_check; ++f) {
            current_total = (current_total + dp_list[i / f]) % mod;
        }

        int boundary_value = i;
        for (int j = 1; j <= i / max_check; ++j) {
            int next_value = i / (j + 1);
            current_total = (current_total + (long long)(boundary_value - next_value) * dp_list[j]) % mod;
            boundary_value = next_value;
        }

        total = (total + current_total) % mod;
        dp_list.push_back(current_total);
    }

    cout << dp_list.back() << "\n";

    return 0;
}
